__NUXT_JSONP__("/svet/stat/aruba/ubytovani", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q){return {data:[{tabsLoad:{tabWhatToSee:c,tabPrice:c,tabPeople:c,tabTrip:c,tabContact:c,tabHotel:c,tabNeighboring:false,tabVideos:k,tabArticles:k,tabWallSockets:f,tabChains:f},place:[{tld:".aw",name:"Aruba",area:180,population:107394,slug:l,id_continent:g,information_chatgpt:"\u003Cp\u003EAruba je ostrov a zároveň zvláštní obec Nizozemska v jižním Karibiku. Ostrov je známý svými bílými písečnými plážemi, teplým a krásným mořem a slunečným počasím po celý rok. Aruba se také pyšní bohatou historií a kulturním dědictvím.\u003C\u002Fp\u003E\n\u003Cp\u003EHlavním městem Aruby je Oranjestad, kde můžete vidět mnoho barokních a koloniálních budov a památek, včetně Fort Zoutman, který sloužil jako vojenská pevnost v minulosti, a budova parlamentu Aruby.\u003C\u002Fp\u003E\n\u003Cp\u003ENejvětší turistickou atrakcí Aruby jsou však jeho pláže. Palm Beach a Eagle Beach jsou dvě nejznámější pláže na ostrově a jsou ideální pro slunění, plavání, šnorchlování nebo windsurfing. Aruba nabízí také bohatou nabídku vodních sportů, jako jsou potápění, parasailing a rybaření.\u003C\u002Fp\u003E\n\u003Cp\u003EKromě turistických aktivit nabízí Aruba také bohaté kulturní dědictví, které je odrazem historie a multikulturalismu ostrova. Můžete navštívit Archeologické muzeum Aruby, kde se dozvíte více o původu ostrova a jeho prvních obyvatelích. Můžete také ochutnat místní kuchyni, která se skládá z různých vlivů, včetně holandské, karibské a latinskoamerické kuchyně.\u003C\u002Fp\u003E\n\u003Cp\u003EDoprava po Arubě je snadná a pohodlná. Můžete využít služeb taxi nebo pronajmout si auto a prozkoumat krásy ostrova na vlastní pěst. Aruba je ideální destinací pro ty, kteří hledají krásné pláže, vodní sporty a relaxaci na slunci, ale také pro ty, kteří se chtějí dozvědět více o kulturním dědictví a historii tohoto krásného karibského ostrova.\u003C\u002Fp\u003E",currency_code:"AWG",currency_name:"arubský florin",money_prices:[{name:"Taxi (cena za km)",value:h,date_update:a},{name:"Hlavní jídlo",value:30,date_update:a},{name:"Chleba",value:f,date_update:a},{name:"Mléko",value:h,date_update:a},{name:"Voda (500ml)",value:m,date_update:a},{name:"Espresso",value:h,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:n,date_update:a},{name:"Pivo",value:n,date_update:a},{name:"Krabička cigaret",value:o,date_update:a},{name:"Big Mac",value:o,date_update:a},{name:"Coca Cola (500ml)",value:h,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:i,date_update:e},{name:"Policie",value:i,date_update:e},{name:"Hasiči",value:i,date_update:e},{name:"Zdravotnická záchranná služba",value:i,date_update:e},{name:"Turistická policie",value:"527-7000",date_update:e},{name:"Pobřežní záchranná služba",value:"915",date_update:e}],phone_prefix:"+297",coordinates:[{latitude:"12.5211",longitude:"-69.9683"}],people_religion:[{name:"křesťanství",value:"76.2%"},{name:"bez vyznání",value:"10.6%"},{name:"hinduismus",value:"2.1%"},{name:"islám",value:"1.9%"},{name:"ostatní náboženství",value:"9.2%"}],people_nationality:[{name:"arubská",value:"68.7%"},{name:"nizozemská",value:"9.1%"},{name:"dominikánská",value:"4.9%"},{name:"kolumbijská",value:"4.6%"},{name:"haitská",value:"4.5%"},{name:"venezuelská",value:"2.9%"},{name:"jiná",value:"5.3%"}],visitors_entry:[{name:"Občanský průkaz",value:"Občanský průkaz nestačí pro vstup do Aruby. Je třeba mít platný cestovní pas.",date_update:d},{name:"Cestovní pas",value:"Pro vstup do Aruby je potřeba mít platný cestovní pas.",date_update:d},{name:"Vízum",value:"Občané České republiky nepotřebují vízum pro pobyt na Arubě déle než 90 dnů. Pokud plánujete pobyt delší než 90 dnů, je třeba zažádat o vízum předem.",date_update:d},{name:"Očkování",value:"Pro vstup na Arubu není povinné očkování. Nicméně, Aruba vyžaduje pro vstup negativní výsledek testu na COVID-19 provedeného nejdéle 72 hodin před odletem do Aruby.",date_update:d},{name:"Cestovní pojištění",value:"Při vstupu na Arubu není vyžadováno mít cestovní pojištění, ale vzhledem k tomu, že zdravotní péče na Arubě je velmi drahá, je vřele doporučeno mít kvalitní zdravotní pojištění, které pokryje případné lékařské náklady.",date_update:d},{name:"Bezpečnostní situace",value:"Aruba je poměrně bezpečná destinace pro turisty, ale jako všude jinde je třeba být obezřetní a mít na paměti základní bezpečnostní opatření, např. nenechávat cennosti a doklady volně v autě, nechodit samotným do opuštěných oblastí apod.",date_update:d},{name:"Další informace",value:"V Arubě se používá americký dolar jako měna. Klima na Arubě je tropické, s celoročně vysokými teplotami a vlhkostí vzduchu. Pokud si plánujete půjčit auto, dejte si pozor na velmi defenzivní styl řízení místních řidičů a také na to, že většina silnic je jednosměrná.",date_update:d}],type_place:p,id_image_cover:j,id_image_hero:j,id_city_main:121,affiliate:[{name:"booking",value:c}],mpz:"AW",alerts:b,zoom:[{google:q,booking:q}],ids_neighboring_countries:[],organization:b,apps:b,links:b,information_author:b,seo_tags:b,language_phrases:b,wall_sockets:b,id:14,facts_place:b,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00"}],imagePlace:[{id:j,name:l,source:"\u002Fworld\u002Fstates\u002F",type:p,author:"pixabay.com",created_at:"2023-04-10T23:52:38.022405+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:g,slug:"severni-amerika",name:"Severní Amerika",area:24490000,population:589000000,population_density:24.04,number_states:23,information_chatgpt:"\u003Cp\u003ESeverní Amerika je třetím největším kontinentem na světě. Rozprostírá se od Arktického oceánu na severu až k Panama kanálu na jihu. Kontinent se skládá ze 23 nezávislých států, včetně Spojených států, Kanady a Mexika, a mnoha dalších závislých území, jako je Grónsko, Bermudy a Portoriko.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je známá svým pestrobarevným kulturním dědictvím, od původních obyvatel až po evropské osadníky a africké otroky. To se odráží v různorodosti jazyků, náboženství, kuchyně, hudby a tradic, které se na kontinentu nacházejí. \u003C\u002Fp\u003E\n\u003Cp\u003EMezi největší atrakce Severní Ameriky patří národní parky, jako jsou Yellowstone, Banff a Yosemite, které nabízejí ohromující přírodní krásy, jako jsou gejzíry, vodopády a divoká zvířata, včetně medvědů a losů. Mezi další populární turistické destinace patří města jako New York, San Francisco, Vancouver a Mexico City, která nabízejí různé zážitky a atrakce.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je také domovem mnoha kultur a tradic, včetně amerického fotbalu, baseballu a basketbalu, kanadského hokeje a mexického fotbalu. Navíc zde najdeme mnoho různých festivalů a oslav, jako například Día de los Muertos v Mexiku nebo Thanksgiving Day v USA a Kanadě.\u003C\u002Fp\u003E\n\u003Cp\u003EV západní části kontinentu najdeme nejvyšší horu Severní Ameriky, Mount McKinley, která se nachází v Aljašce. Východní část kontinentu pak tvoří rozsáhlé planiny, jako jsou Velká pláň a Floridská pláň. \u003C\u002Fp\u003E\n\u003Cp\u003EKlima Severní Ameriky se výrazně liší podle oblastí. Na severu a v oblastech vysokohorských pásem se vyskytují chladné a sněhové zimy, zatímco na jihu a na pobřeží Pacifiku jsou zimy mírnější. Celkově však kontinent nabízí mnoho slunečných a teplých dnů, zejména v letních měsících.\u003C\u002Fp\u003E\n\u003Cp\u003ENa kontinentu najdeme také mnoho různých druhů fauny a flóry. Mezi nejvíce známé zvířata patří medvědi, vlci, losi, bizoni, krokodýli a mnoho dalších. Severní Amerika má také rozmanitou flóru, včetně různých druhů stromů, květin a rostlin, jako jsou kaktusy a douglasky.\u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika má významnou roli ve světové ekonomice. Spojené státy jsou největší ekonomikou na světě, zatímco Kanada je jedním z největších světových výrobců surovin, jako je dřevo, zemní plyn a ropa. Mexiko je důležitým producentem automobilů, elektroniky a potravin. \u003C\u002Fp\u003E\n\u003Cp\u003ENavzdory tomu má Severní Amerika také mnoho výzev. Mezi největší problémy patří změna klimatu, nerovnost, přistěhovalectví a ochrana přírodních zdrojů. Zároveň však existuje mnoho iniciativ a organizací, které se snaží tyto problémy řešit a posilovat spolupráci mezi jednotlivými zeměmi kontinentu. \u003C\u002Fp\u003E\n\u003Cp\u003ESeverní Amerika je fascinujícím kontinentem s mnoha přírodními krásami, kulturními tradicemi a ekonomickým vlivem na světovou scénu. Bez ohledu na to, zda se jedná o turistickou destinaci nebo oblast zájmu z hlediska vědy a průmyslu, Severní Amerika nabízí mnoho možností pro objevování a poznávání. \u003C\u002Fp\u003E",coordinates:[{latitude:47.497912,longitude:-100.540235}],type_place:"continent",id_image_cover:g,id_image_hero:g,zoom:[{google:m,booking:f}],information_author:b,seo_tags:b,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00"}]}],fetch:{},mutations:[]}}("01-2021",null,true,"04-2023","05-2023",3,1,3.5,"911",21,0,"aruba",2,4,12,"state",11)));